/** Прокрутить вниз до элемента, текст которого целиком совпадает с регулярным выражением. */
export async function scrollToMatch(re: string, max = 12) {
  for (let i = 0; i <= max; i++) {
    const el = await byTextMatches(re);
    if (await el.isDisplayed().catch(() => false)) return el;
    await swipeUp();
  }
  throw new Error(`Не найден текст (regex) после прокрутки: ${re}`);
}

/** Поле ввода сразу после подписи (label) — «טקסט התפילה», «מי הקליט», «שם המאשר», «הערה לאישור (לא חובה)».
 *  TODO калибровка: если в приложении у полей есть testID (в web — admin-field-*), можно заменить на resource-id. */
export function fieldAfter(label: string) {
  return driver.isAndroid
    ? $(`//*[@text="${label}"]/following::android.widget.EditText[1]`)
    : $(`(//*[@name="${label}" or @label="${label}"]/following::*[self::XCUIElementTypeTextView or self::XCUIElementTypeTextField])[1]`);
}
export async function setField(label: string, value: string) {
  await scrollToText(label);
  const f = await fieldAfter(label);
  await f.waitForDisplayed();
  await f.clearValue();
  if (value) await f.setValue(value);
}
export async function readField(label: string): Promise<string> {
  await scrollToText(label);
  const f = await fieldAfter(label);
  await f.waitForDisplayed();
  return (driver.isAndroid ? await f.getText() : (await f.getAttribute('value')) ?? (await f.getText())) ?? '';
}

/** Нажать самый нижний видимый элемент с точным текстом (у «אישור ופרסום» есть заголовок карточки и кнопка с тем же текстом). */
export async function tapLowest(text: string) {
  let best: WebdriverIO.Element | undefined;
  let bestY = -1;
  for (const el of await allByText(text)) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const { y } = await el.getLocation();
    if (y > bestY) { bestY = y; best = el; }
  }
  if (!best) throw new Error(`Нет видимого «${text}»`);
  await best.click();
}

