/** Вход в админку из профиля: «מעבר לפרטים שלי» → раздел «ניהול» → «ממשק ניהול התוכן» → «ניהול תכני תפילה» (AD-02).
 *  TODO калибровка: если в приложении точка входа иная (пункт меню/вкладка) — поменять только здесь. */
export async function openAdminHome() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToText('ממשק ניהול התוכן')).click();
  await (await byText('ניהול תכני תפילה')).waitForDisplayed({ timeout: 20000 });
}

/** Регулярка карточки «<молитва> · נוסח <נוסח>» (разделитель — любой символ, как в web-тестах). */
export const cardRe = (prayer: string, nusach: string) => `${prayer}\\s*.\\s*נוסח ${nusach}`;

/** Админка → карточка молитвы (например «ערבית», «אשכנז») → экран молитвы с «N מתוך M קטעים מאושרים». */
export async function openAdminPrayer(prayer: string, nusach: string) {
  await openAdminHome();
  await (await scrollToMatch(cardRe(prayer, nusach))).click();
  await (await byTextMatches('\\d+ מתוך \\d+ קטעים מאושרים')).waitForDisplayed({ timeout: 20000 });
}

/** На экране молитвы в админке открыть קטע по названию (в «קטעי התפילה») → «עריכת קטע». */
export async function openSection(title: string) {
  await scrollToText('קטעי התפילה');
  await scrollToText(title);
  const el = await byText(title);
  await el.waitForDisplayed();
  await el.click();
  await (await byText('עריכת קטע')).waitForDisplayed({ timeout: 20000 });
}

/** Открыть קטע заново (после утверждения приложение возвращает на экран молитвы с окном «אישור»). */
export async function reopenSection(prayer: string, nusach: string, title: string) {
  await openAdminPrayer(prayer, nusach);
  await openSection(title);
}

