export async function setBody(text: string) { await setField('טקסט התפילה', text); }
export async function readBody() { return readField('טקסט התפילה'); }

/** «שמירת טיוטה» → появляется «מחיקת הטיוטה» и карточка «אישור ופרסום» с «שם המאשר» (ee5747-repl-2-draft-admin). */
export async function saveDraft() {
  await (await scrollToText('שמירת טיוטה')).click();
  await scrollToText('מחיקת הטיוטה');
  await expect(byText('מחיקת הטיוטה')).toBeDisplayed();
}

/** Есть ли черновик (кнопка «מחיקת הטיוטה»). */
export async function hasDraft() {
  try { await scrollToText('מחיקת הטיוטה', 6); return true; } catch { return false; }
}

/** «מחיקת הטיוטה» (+ подтверждение, если появится). TODO калибровка: текст кнопки подтверждения в окне удаления черновика. */
export async function discardDraft() {
  await (await scrollToText('מחיקת הטיוטה')).click();
  await driver.waitUntil(async () => {
    if (!(await shown(byText('מחיקת הטיוטה')))) return true;
    for (const t of ['מחיקה', 'מחק', 'אישור']) {
      const b = await byText(t);
      if (await b.isDisplayed().catch(() => false)) { await b.click().catch(() => {}); break; }
    }
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: '«מחיקת הטיוטה» не убрала черновик' });
}

/** «אישור ופרסום» с заметкой-меткой → окно «הקטע אושר ומוצג עכשיו למשתמשים.» → «אישור». Имя утверждающего — как предзаполнено. */
export async function approveDraft(marker: string) {
  await setField('הערה לאישור (לא חובה)', marker);
  await scrollToText('אישור ופרסום');
  await tapLowest('אישור ופרסום');
  await (await byText('הקטע אושר ומוצג עכשיו למשתמשים.')).waitForDisplayed({ timeout: 30000 });
  await tapText('אישור');
}

/** Запись истории утверждений со своей меткой. */
export async function historyEntry(marker: string) {
  await scrollToText('היסטוריית אישורים');
  return scrollToText(marker);
}

/**
 * Вернуть текст קטע посимвольно (в finally каждого @data-теста): открыть קטע, при расхождении — вставить оригинал,
 * «שמירת טיוטה» → «אישור ופרסום»; при совпадении, но висящем черновике — «מחיקת הטיוטה». Проверка: поле = оригинал.
 */
export async function restoreSectionText(prayer: string, nusach: string, title: string, orig: string, tag: string) {
  await reopenSection(prayer, nusach, title);
  if ((await readBody()) !== orig) {
    await setBody(orig);
    await saveDraft();
    await approveDraft(qaMarker(`${tag}-restore`));
    await reopenSection(prayer, nusach, title);
  } else if (await hasDraft()) {
    await discardDraft();
  }
  const now = await readBody();
  if (now !== orig) throw new Error(`Текст «${title}» не вернулся посимвольно: ${now.length} симв. против ${orig.length}`);
}

