export const REC_CARD = 'הקראת הקטע (MP3)';
export const REC_NONE = 'לקטע הזה אין עדיין הקראה.';                 // rec-G1, upfail-5
export const REC_PENDING = 'ממתינה לאישור';                          // «ממתינה לאישור — המשתמשים עדיין לא שומעים אותה.» (rec-A2)
export const REC_APPROVE_BTN = 'אישור ההקראה ופרסומה';                // rec-A2
export const REC_APPROVED_RE = '(?s)אושרה על ידי .*מוצעת להשמעה למשתמשים.*';   // rec-C
export const REC_NOT_MATCHING = 'לא תואמת את הטקסט הנוכחי של הקטע';   // rec-F2
export const REC_REMOVE_BTN = 'הסרת ההקראה';
export const REC_REMOVED = 'ההקראה הוסרה.';                           // rec-G1
export const REC_UPLOAD_BTN = 'העלאת קובץ MP3';

/** Положить файл на телефон для системного пикера. Android — /sdcard/Download/<name>. iOS — не поддерживается (см. canPickFiles). */
export async function pushToDownloads(name: string, base64: string) {
  const remote = `/sdcard/Download/${name}`;
  await driver.pushFile(remote, base64);
  // Обновить индекс MediaStore, чтобы DocumentsUI сразу увидел файл (нужен --relaxed-security; без него — пропускаем).
  try {
    await driver.execute('mobile: shell', { command: 'am', args: ['broadcast', '-a', 'android.intent.action.MEDIA_SCANNER_SCAN_FILE', '-d', `file://${remote}`] });
  } catch { /* без relaxed-security: pushFile обычно и так индексируется */ }
  return remote;
}
export async function removeFromDevice(remote: string) {
  try { await driver.execute('mobile: shell', { command: 'rm', args: ['-f', remote] }); } catch { /* без relaxed-security — оставить */ }
}

/** Системный выбор файла автоматизируем только на Android (DocumentsUI). На iOS файл в «Файлы» через Appium не положить → @manual-check. */
export const canPickFiles = () => driver.isAndroid;

/**
 * Выбрать файл в системном пикере Android (DocumentsUI): сначала в открывшемся списке («אחרונים»/Recent),
 * иначе меню корней → «הורדות»/«Downloads» → файл.
 * TODO калибровка: подпись кнопки меню корней на устройстве (he/en) и наличие «הורדות» в списке.
 */
export async function pickInAndroidPicker(fileName: string) {
  const file = await byText(fileName);
  if (await file.waitForDisplayed({ timeout: 10000 }).then(() => true, () => false)) { await file.click(); return; }
  const roots = await $('android=new UiSelector().descriptionMatches("(?i)(show roots|הצג.*|.*שורש.*|.*תפריט.*)")');
  if (await roots.isDisplayed().catch(() => false)) await roots.click();
  for (const t of ['הורדות', 'Downloads', 'Download']) {
    const d = await byText(t);
    if (await d.isDisplayed().catch(() => false)) { await d.click(); break; }
  }
  await file.waitForDisplayed({ timeout: 15000 });
  await file.click();
}

/** На экране «עריכת קטע»: «מי הקליט» → «העלאת קובץ MP3» → выбор файла в пикере. */
export async function uploadRecording(fileName: string, recordedBy: string) {
  await scrollToText(REC_CARD);
  await setField('מי הקליט', recordedBy);
  await (await scrollToText(REC_UPLOAD_BTN)).click();
  await pickInAndroidPicker(fileName);
}

/** Удалить запись, если она есть («הסרת ההקראה» + подтверждение, если появится) → «ההקראה הוסרה.».
 *  TODO калибровка: текст кнопки в окне подтверждения удаления (AD-07: «удалить запись → подтверждение»). */
export async function removeRecordingIfAny() {
  let btn;
  try { btn = await scrollToText(REC_REMOVE_BTN, 8); } catch { return false; }
  await btn.click();
  await driver.waitUntil(async () => {
    if (await shown(byTextContains(REC_NONE))) return true;
    for (const t of ['הסרה', 'הסר', 'אישור']) {
      const b = await byText(t);
      if (await b.isDisplayed().catch(() => false)) { await b.click().catch(() => {}); break; }
    }
    return false;
  }, { timeout: 30000, interval: 700, timeoutMsg: '«הסרת ההקראה» не убрала запись' });
  return true;
}

/** Сводка карточки «הקראות הקטעים» на экране молитвы (upfail-final-summary-15). */
export const REC_SUMMARY_RE = '(?s)מאושרות: (\\d+) · ממתינות לאישור: (\\d+) · לא תואמות לטקסט: (\\d+) · בלי הקראה: (\\d+).*';
export async function recordingSummary() {
  await scrollToText('הקראות הקטעים');
  const el = await scrollToMatch(REC_SUMMARY_RE, 4);
  const t = (await el.getText()) || '';
  const m = t.match(/מאושרות: (\d+) · ממתינות לאישור: (\d+) · לא תואמות לטקסט: (\d+) · בלי הקראה: (\d+)/);
  if (!m) throw new Error(`Сводка «הקראות הקטעים» не разобрана: ${t}`);
  return { approved: +m[1], pending: +m[2], notMatching: +m[3], none: +m[4] };
}

