/** Статус קטע в списке «קטעי התפילה» под его названием: «מאושר · <имя>, <дата>, <время>» или «טקסט זמני, טרם אושר». */
export async function sectionStatus(title: string): Promise<string> {
  await scrollToText('קטעי התפילה');
  await scrollToText(title);
  const el = driver.isAndroid
    ? await $(`//*[@text="${title}"]/following::*[starts-with(@text,"מאושר") or starts-with(@text,"טקסט זמני") or starts-with(@text,"טיוטה")][1]`)
    : await $(`(//*[@name="${title}" or @label="${title}"]/following::*[starts-with(@label,"מאושר") or starts-with(@label,"טקסט זמני") or starts-with(@label,"טיוטה")])[1]`);
  await el.waitForDisplayed();
  return (driver.isAndroid ? await el.getText() : (await el.getAttribute('label')) ?? '') ?? '';
}

